import type {ArticleSection,Branch,ReadingEntry,SourceLink} from '../types/philosophy';

const section=(id:string,title:string,paragraphs:string[],relatedBranchIds?:string[],relatedPhilosopherIds?:string[],relatedWorkTitles?:string[]):ArticleSection=>({id,title,paragraphs,relatedBranchIds,relatedPhilosopherIds,relatedWorkTitles});
const reading=(author:string,title:string,difficulty:ReadingEntry['difficulty'],whyRead:string,type:ReadingEntry['type']='primary'):ReadingEntry=>({author,title,difficulty,type,whyRead});
const source=(label:string,url:string,type:SourceLink['type'],notes?:string):SourceLink=>({label,url,type,notes});

export const kantianismBranchArticle:ArticleSection[]=[
  section('contested-inheritance','A contested inheritance, not Kant repeated',[
    'Kantianism is the long and diverse history of philosophers who inherit, revise, defend, or contest Immanuel Kant’s critical project. It has no single creed. Some Kantians emphasize the conditions that make objective knowledge possible; others emphasize autonomy, dignity, and moral obligation; still others develop accounts of aesthetic judgment, historical reason, scientific objectivity, political legitimacy, or the limits of metaphysics. A thinker may be Kantian in one domain and anti-Kantian in another. The name therefore marks a family of arguments and methods, not agreement with every proposition Kant wrote.',
    'The inheritance begins with a productive instability. Kant claims that cognition depends on forms and concepts contributed by finite knowers, while knowledge remains answerable to an empirically real world. He limits theoretical knowledge to possible experience, yet gives freedom and moral law practical authority. He treats reason as self-critical and autonomous, but his account of human beings includes racial, gendered, civilizational, and able-bodied assumptions that later readers cannot responsibly ignore. Each of these conjunctions creates different ways to continue Kant and different reasons to break with him.',
    'It is useful to distinguish historical Kant scholarship from philosophical Kantianism. A historian may reconstruct Kant accurately while rejecting his arguments. A contemporary theorist may use a Kantian idea—transcendental conditions, self-legislation, public reason, respect for persons—without claiming textual orthodoxy. The strongest uses of the label say which element is inherited, how it is transformed, and what has been discarded. Calling every theory of rules, rights, or mental structure Kantian makes the term empty; demanding complete fidelity makes it historically impossible.'
  ],['epistemology','metaphysics','ethics','political-philosophy'],['kant'],['Critique of Pure Reason','Groundwork of the Metaphysics of Morals']),
  section('first-reception','The first readers: clarification quickly becomes reconstruction',[
    'The Critique of Pure Reason did not instantly found a unified school. Early reviewers disagreed about whether transcendental idealism was a version of Berkeleyan idealism, an answer to skepticism, or an unstable compromise. Kant issued the Prolegomena and a substantially revised second edition partly to redirect reception. Karl Leonhard Reinhold’s Letters on the Kantian Philosophy made the moral and religious significance of critique accessible to a wider public, then sought a single first principle from which the system could be derived. Popularization thus became reconstruction almost immediately.',
    'Friedrich Heinrich Jacobi sharpened a difficulty that would haunt the tradition: Kant seems to require things in themselves to affect sensibility, yet denies that causality can be known beyond possible experience. Jacobi’s objection suggested that one could not enter the critical system without the thing in itself and could not remain in it with that concept. Gottlob Ernst Schulze pressed skeptical objections against the alleged deduction of cognitive conditions. Salomon Maimon questioned Kant’s strict separation of sensibility and understanding and demanded a deeper account of how heterogeneous elements cooperate in cognition.',
    'These first disputes established recurring choices. Should critique remain an investigation of finite cognitive limits, or should philosophy derive a systematic first principle? Is the thing in itself a necessary boundary concept, a contradictory leftover, or a misleading way of marking inexhaustibility? Does objectivity require a given element independent of conceptual activity, or can the distinction between given and thought be reconstructed within one process? Later Kantians repeatedly rediscover these alternatives, often without accepting the answers of Kant’s first readers.'
  ],['german-idealism','skepticism','epistemology'],['kant','fichte'],['Prolegomena to Any Future Metaphysics','Critique of Pure Reason']),
  section('fichte','Fichte: from a critique of faculties to self-positing activity',[
    'Fichte transformed the demand for a unified foundation into the Wissenschaftslehre, or science of knowledge. Rather than begin from a separately existing thing in itself that supplies material to a receptive subject, he begins from the activity through which the I posits itself and distinguishes itself from a not-I. This is not the everyday ego inventing the world at whim. Fichte aims to disclose the conditions of finite self-conscious agency, where resistance, limitation, striving, and recognition belong to the structure through which an agent can act and know.',
    'The practical dimension is decisive. Finite agency experiences the world as a field of resistance within which freedom must be realized, not as a dream projected by an isolated mind. Fichte develops Kantian autonomy toward a more active account of vocation, right, and relations among rational beings. At the same time, his attempts to derive theoretical structure from self-positing intensify the idealist tendency Kant had limited. Kant publicly rejected the claim that Fichte’s system represented the critical philosophy, demonstrating that historical influence does not establish authorized succession.',
    'Fichte’s legacy divides interpretation. Some readers find a radical subjective idealism that absorbs objectivity into the I. Others emphasize that the I is an impersonal normative activity and that the not-I marks genuine constraint. The disagreement anticipates later versions of Kantianism centered on spontaneity, norm-governed judgment, and the social conditions of agency. It also raises a permanent question: can a philosophy explain the authority of norms from the activity of reason without making reason answerable only to itself?'
  ],['german-idealism','epistemology','ethics'],['fichte','kant'],['Foundations of the Entire Science of Knowledge','The Vocation of Man']),
  section('schelling-hegel','Schelling and Hegel: completing Kant by criticizing his limits',[
    'Schelling argued that Kantian divisions between nature and freedom, receptivity and spontaneity, or appearance and intelligible reality could not remain fixed. His philosophies of nature describe nature as productive and dynamically organized rather than as inert material awaiting subjective form. His accounts of identity, art, and freedom seek a ground from which subject and object can be understood as differentiated expressions of a deeper unity. The third Critique’s treatment of organisms and aesthetic judgment becomes a bridge toward claims Kant himself refused to make as theoretical knowledge.',
    'Hegel’s relation to Kant is equally intimate and adversarial. He accepts that philosophy must justify its categories rather than simply apply inherited metaphysics, and he inherits autonomy as a defining modern achievement. Yet he argues that Kant too often leaves oppositions externally paired: concept and intuition, freedom and nature, universal law and particular motivation, noumenal and phenomenal. Hegel’s dialectical project tries to show how concepts develop through their internal inadequacies and how freedom becomes actual in social practices and institutions, not only in an individual will abstracted from history.',
    'Whether German Idealism is Kantianism depends on the standard used. It clearly grows from problems set by Kant and frequently presents itself as completing critique. It also abandons Kant’s prohibition on knowledge beyond possible experience, his fixed table of categories, and his insistence that finite discursive cognition cannot achieve intellectual intuition. Some histories treat Fichte, Schelling, and Hegel as the first Kantians; others treat their systems as precisely the speculative metaphysics against which a later return to Kant was required.'
  ],['german-idealism','metaphysics','aesthetics'],['kant','fichte','schelling','hegel'],['Critique of the Power of Judgment','Phenomenology of Spirit','Science of Logic']),
  section('nineteenth-critics','Schopenhauer, Herbart, Fries, and nineteenth-century criticism',[
    'The nineteenth century did not move in one line from Kant to Hegel. Schopenhauer praised the distinction between appearance and thing in itself while identifying will as the inner character of reality, a step Kant’s theoretical limits appear to forbid. He rejected Kant’s categorical imperative as an abstract restatement of theological morality and made compassion central to ethics. His philosophy is Kantian in its starting architecture and anti-Kantian in its metaphysical confidence, moral psychology, aesthetics, and pessimism.',
    'Johann Friedrich Herbart resisted the idealist attempt to derive reality from the activity of consciousness and pursued a pluralist realism. Jakob Friedrich Fries defended a form of critical philosophy while grounding our access to a priori principles in empirical self-observation, provoking charges of psychologism. Friedrich Eduard Beneke developed psychology against speculative idealism. These figures show that nineteenth-century Kant reception included realist, psychological, scientific, and pedagogical alternatives that later textbook narratives often hide behind the dramatic succession from Fichte to Hegel.',
    'Materialists, positivists, theologians, and emerging historical disciplines also challenged the critical system. New geometries and developments in physiology raised questions about the status of space and a priori form. Historical scholarship made fixed categories look culturally situated. Natural science seemed either to vindicate Kant’s demand for conditions of knowledge or to replace philosophical critique with empirical investigation. By mid-century, “back to Kant” could mean many things: abandon speculative systems, resist reductive materialism, secure philosophy’s independence from psychology, or rebuild the theory of knowledge around modern science.'
  ],['metaphysics','philosophy-of-science','german-idealism'],['schopenhauer','kant'],['The World as Will and Representation','Critique of Pure Reason']),
  section('marx-nietzsche','Marx, Nietzsche, and critics of Kantian abstraction',[
    'Marx inherits the demand that apparent facts be understood through conditions that make them possible, but relocates those conditions in labor, social relations, property, class, and historical production. He criticizes moral and political abstractions that treat formally free persons apart from material dependence. Although Marx is more directly shaped by Hegel and political economy, later theorists describe a Kantian strand in critique whenever social arrangements are assessed by norms they implicitly claim or when inquiry reconstructs the conditions of a form of social objectivity.',
    'Nietzsche attacks the authority of universal moral law, the intelligible moral agent, disinterested judgment, and the confidence that reason can legislate independently of embodied drives. He treats moral systems genealogically, asking which histories and forms of life produced their claims. Yet Nietzsche’s practice of examining the limits and interests of reason can resemble critique turned against Kantian morality. The resemblance should not obscure opposition: Nietzsche rejects equal dignity and universal obligation, while Kantian ethics makes their authority central.',
    'These criticisms establish a challenge that later Kantians cannot answer by repeating the categorical imperative. Are universal norms genuinely independent of domination, or do they conceal the standpoint of socially privileged agents? Can formal rights address material power and dependency? Does transcendental inquiry reveal necessary conditions or project historically local concepts as universal? Kantianism survives these objections only by explaining how universal validity can be open to historical, social, genealogical, and institutional criticism without dissolving into whatever norms a society already accepts.'
  ],['political-philosophy','ethics','continental-philosophy'],['kant','marx','nietzsche'],['On the Genealogy of Morality','Capital']),
  section('back-to-kant','The “back to Kant” movements and philosophy’s new task',[
    'Calls to return to Kant gathered force from the 1850s through the 1870s. They were responses to the decline of Hegelian system-building, the prestige of the natural sciences, disputes about materialism, and uncertainty about philosophy’s distinctive method. Friedrich Albert Lange, Hermann von Helmholtz, Kuno Fischer, Otto Liebmann, and Eduard Zeller approached Kant from different directions. Some connected a priori form to the physiology of perception; others treated criticism as a safeguard against both speculative metaphysics and reductive naturalism.',
    'The slogan did not demand restoration of Kant’s complete doctrine. New scientific theories made his Euclidean geometry, Newtonian background, fixed categories, and account of matter objects of revision. The return instead selected a question: what conditions allow a claim, practice, or science to possess objective validity? This “transcendental” question moves from causal explanation of how a belief arose to justification of the norms under which it can count as knowledge. Its defenders argued that psychology can describe thinking without determining what one ought to believe.',
    'By the late nineteenth century, neo-Kantianism became an institutionally powerful movement in German universities, journals, classrooms, and histories of philosophy. Yet the singular label conceals schools that disagreed about sensibility, values, natural science, history, and the thing in itself. The movement’s academic success also shaped what counted as canonical philosophy and who could occupy its institutions. Reconstructing it requires attention to universities and disciplines as well as doctrines.'
  ],['epistemology','philosophy-of-science','german-idealism'],['kant'],['History of Materialism','Kant and the Epigones']),
  section('marburg','Marburg neo-Kantianism: science, method, and functional objectivity',[
    'The Marburg school associated with Hermann Cohen, Paul Natorp, and Ernst Cassirer treated the transcendental method as an inquiry into the conditions of objective scientific knowledge. It rejected the idea that knowledge begins with a raw sensory given later organized by concepts. The object of knowledge is approached through an ongoing process of lawful determination within science. Concepts are functions for organizing relations, not mental copies of substances already completed outside inquiry.',
    'Cohen reconstructed Kant through mathematical physics and often treated the thing in itself as a task or limiting idea rather than an independently affecting object. Natorp developed a systematic idealism and extended the method to psychology, pedagogy, and social philosophy. Cassirer moved from scientific concepts to a broader philosophy of symbolic forms, examining language, myth, art, and culture as distinct ways human beings articulate a world. None simply defended Kant’s original table of categories or Newtonian science as timeless.',
    'Marburg philosophy raises a productive tension between objectivity and historical change. If a priori principles are conditions of current science, how can they change with scientific revolutions without becoming merely empirical conventions? Later philosophers of science develop “relativized” or “dynamic” a priori frameworks that retain constitutive principles while allowing revision. Critics worry that defining objects through ideal scientific determination makes reality too dependent on method or turns successful science into an unquestioned tribunal. Defenders answer that inquiry remains corrigible precisely because no final given closes it.'
  ],['philosophy-of-science','epistemology','analytic-philosophy'],['kant'],['Kant’s Theory of Experience','Substance and Function','Philosophy of Symbolic Forms']),
  section('southwest','Southwest neo-Kantianism: value, history, and cultural science',[
    'The Southwest or Baden school, especially Wilhelm Windelband and Heinrich Rickert, also distinguished justification from psychological genesis, but it emphasized value and the methods of historical inquiry. Natural science seeks general laws; historical disciplines select and organize singular events through their relation to culturally significant values. This does not mean that historians may invent facts according to preference. It means that no complete inventory of reality determines by itself which persons, actions, or transformations become historically meaningful objects.',
    'Windelband’s contrast between nomothetic and idiographic inquiry distinguishes law-seeking from individualizing methods without simply assigning every discipline to one box. Rickert develops a theory of concept formation and objective validity intended to protect historical scholarship from both naturalistic reduction and subjective relativism. Emil Lask rethinks form, material, and validity in ways that influenced later phenomenology. The school thereby extends critique beyond Kant’s concentration on mathematical natural science.',
    'Marburg and Southwest neo-Kantians share anti-psychologism and a commitment to transcendental inquiry, but their differences are substantial. One foregrounds the lawful construction of scientific objects; the other foregrounds value-relevance and cultural individuality. Their debate asks whether reason’s unity lies in one scientific method or in differentiated normative domains. It also warns against equating Kantianism with epistemology alone: theories of culture, history, law, religion, and education were central to the movement’s ambitions.'
  ],['epistemology','philosophy-of-science','continental-philosophy'],['kant'],['Preludes','The Limits of Concept Formation in Natural Science']),
  section('international-neokantianism','International neo-Kantianisms and disputed boundaries',[
    'Neo-Kantian philosophy extended beyond the two German schools. Alois Riehl defended a critical realism; Hans Vaihinger developed a philosophy of “as if”; Leonard Nelson renewed Friesian criticism; and diverse French, British, Italian, Russian, and other thinkers adapted Kantian themes. In Britain, T. H. Green and other idealists connected autonomy and self-realization to social institutions, though their relation to Hegel makes classification contested. In France, Charles Renouvier and Léon Brunschvicg developed distinct critical philosophies rather than branches of a German organization.',
    'Jewish neo-Kantian thinkers transformed the tradition’s religious and ethical significance. Cohen’s later philosophy of religion connects ethical monotheism, repentance, law, and the relation to the suffering other, challenging any picture of Marburg thought as philosophy of physics alone. Cassirer’s exile and analysis of political myth demonstrate how symbolic philosophy responded to the catastrophe of European institutions. Such histories complicate a triumphal account in which one school smoothly hands reason to the twentieth century.',
    'The boundaries remain disputed because “neo-Kantian” can name an institutional movement, a period slogan, or any later revision of Kant. A narrow usage reserves the capitalized historical term for the Marburg and Southwest schools. A broader usage includes independent returns to critical philosophy. The narrow sense protects historical specificity; the broader sense captures real networks of argument but risks turning most modern philosophy into neo-Kantianism. A responsible account states which sense it uses.'
  ],['philosophy-of-religion','political-philosophy','philosophy-of-science'],['kant'],['Religion of Reason Out of the Sources of Judaism','The Myth of the State']),
  section('parting-ways','Decline, exile, and the analytic–continental “parting of the ways”',[
    'Neo-Kantianism’s institutional dominance weakened after the First World War. A younger generation criticized it as formal, academic, detached from existence, or unable to reach reality. Husserlian phenomenology, Heidegger’s fundamental ontology, logical empiricism, and new forms of philosophical anthropology all defined themselves partly against neo-Kantian teachers. Political upheaval, antisemitism, exile, and the destruction of German academic life under National Socialism then broke institutions and dispersed scholars. Philosophical succession cannot be explained as an argument alone.',
    'The later distinction between analytic and continental philosophy obscures shared Kantian ancestry. Carnap studied with neo-Kantian and phenomenological teachers; Heidegger’s early formation included Southwest neo-Kantianism; Cassirer debated Heidegger at Davos; Reichenbach reworked the constitutive a priori in philosophy of science. The apparent fork between logical analysis and existential phenomenology was shaped through rival responses to common problems of objectivity, meaning, finitude, science, and culture.',
    'Treating this moment as a clean split imposes later professional identities on a dense field. Analytic philosophers continued to argue about conceptual conditions, modality, perception, and normativity. Continental philosophers continued to transform transcendental method, autonomy, judgment, and critique. The labels identify real institutions and styles, but neither tradition owns or escapes Kant. Their different Kants became ways of defining what philosophy itself should do.'
  ],['analytic-philosophy','continental-philosophy','phenomenology'],['kant','heidegger'],['Being and Time','The Logical Structure of the World']),
  section('analytic-reception','Analytic inheritances: rejection, reconstruction, and transcendental arguments',[
    'Early analytic philosophy often defined itself against British idealism and speculative system, which could make Kant appear part of the problem. Developments in logic, non-Euclidean geometry, relativity, and empiricist philosophy of science challenged Kant’s specific claims about synthetic a priori knowledge. Yet the questions returned. C. I. Lewis developed a pragmatic a priori; Rudolf Carnap distinguished linguistic frameworks; and philosophers asked which conceptual structures are necessary for identifying objects, causes, persons, or an objective world.',
    'P. F. Strawson’s The Bounds of Sense offered an influential selective reconstruction. It sought to separate durable arguments about the conceptual conditions of objective experience from transcendental idealism and other parts of Kant’s system Strawson regarded as indefensible. This “descriptive metaphysics” asks what general structure our thought about an objective world must possess. Critics argue that removing transcendental idealism changes the arguments that were supposed to support the structure, while defenders treat reconstruction as legitimate philosophical inheritance.',
    'Transcendental arguments became a broader analytic strategy: begin from an apparently unavoidable feature of experience or practice and infer conditions required for its possibility. Such arguments have been used against skepticism and in accounts of self-consciousness, agency, language, and other minds. Their strength and reach remain disputed. An argument may show only what we must believe, not how reality independently is; a skeptic may accept local practices without the ambitious conclusion; and claims of necessity may conceal contingent features of one conceptual scheme.'
  ],['analytic-philosophy','epistemology','metaphysics'],['kant'],['The Bounds of Sense','Critique of Pure Reason']),
  section('sellars-mcdowell','Sellars, McDowell, and the space of reasons',[
    'Wilfrid Sellars renewed Kantian themes while attacking the “myth of the given,” the idea that bare sensory episodes can justify beliefs without already standing in norm-governed relations. Knowledge belongs to a space of reasons in which claims can be justified, challenged, and revised. Sellars nevertheless preserves a causal role for sensory receptivity and seeks a synoptic relation between the manifest image of persons and the scientific image. His Kant is a resource for understanding conceptual activity, modality, and normativity rather than an authority whose complete system must be accepted.',
    'John McDowell argues that experience must already possess conceptual form if it is to provide rational constraint rather than merely cause belief. He draws on Kant’s claim that intuitions without concepts and concepts without intuitions cannot yield cognition, while resisting a picture in which spontaneity becomes frictionless. Other interpreters defend nonconceptual content or a sharper independence for intuition. The dispute crosses historical exegesis and contemporary philosophy of perception.',
    'Robert Brandom develops an inferential and social account of conceptual content in which commitments gain meaning through practices of giving and asking for reasons. He connects this lineage through Kant and Hegel, emphasizing judgment, normativity, and mutual recognition. Critics ask whether such accounts over-intellectualize perception, marginalize embodiment and affect, or make nonhuman cognition difficult to recognize. Analytic Kantianism remains a live family precisely because receptivity and spontaneity have not settled into one accepted balance.'
  ],['analytic-philosophy','philosophy-of-mind','epistemology'],['kant','hegel'],['Empiricism and the Philosophy of Mind','Mind and World','Making It Explicit']),
  section('continental-inheritances','Phenomenology, Heidegger, and continental transformations',[
    'Husserl’s transcendental phenomenology shares Kant’s concern with conditions of objectivity but reconstructs them through intentional analysis and the phenomenological reduction. Consciousness is directed toward objects through structures that can be described rather than inferred as hidden mechanisms. Husserl criticizes psychologism and investigates time, embodiment, intersubjectivity, and the lifeworld. Whether his transcendental idealism is Kantian, Cartesian, or distinct remains a central interpretive question.',
    'Heidegger radicalizes finitude. His “ontological difference” and analysis of being-in-the-world reject the picture of an isolated subject first receiving data and then constructing an external world. In his reading of Kant, imagination and temporality reveal a more fundamental basis for finite understanding than later portions of the first Critique acknowledge. Heidegger presents himself as retrieving an unrealized possibility in Kant while redirecting transcendental inquiry from the conditions of objects to the question of being.',
    'Later phenomenology, hermeneutics, existentialism, and deconstruction continue and criticize Kantian structures. Sartre and Beauvoir transform freedom through situation and relations with others; Merleau-Ponty centers embodied perception; Gadamer questions the ideal of method detached from historical understanding; Derrida reworks conditions of possibility as conditions that also produce instability. These inheritances are not a single continental Kantianism. They share a practice of finding limits, exclusions, and enabling conditions within concepts that present themselves as universal.'
  ],['phenomenology','continental-philosophy','existentialism'],['kant','husserl','heidegger','sartre','beauvoir','derrida'],['Ideas I','Being and Time','Phenomenology of Perception']),
  section('critical-theory','Critical theory and communicative transformations of reason',[
    'The Frankfurt School inherits Kant through Hegel, Marx, Weber, psychoanalysis, and social research. Horkheimer and Adorno criticize an instrumental reason that turns enlightenment into domination when calculation, control, and self-preservation become its entire form. Their critique is not a simple rejection of reason; it confronts reason with its emancipatory promise and asks why formally rational societies reproduce unfreedom. Kantian autonomy survives as a damaged standard rather than a completed possession.',
    'Adorno’s negative dialectics resists the pressure to make particulars fully identical with concepts. A critical system must attend to what its classifications exclude and to suffering that demonstrates their failure. This reverses triumphalist Kantianism: the point of a limit is not merely to police metaphysical speculation but to prevent conceptual mastery from declaring reality exhausted. Aesthetic judgment and the autonomy of art become resources for experiencing forms of nonidentity.',
    'Habermas reconstructs practical reason through communication. Instead of locating moral validity in an isolated subject legislating universal law, discourse ethics asks whether norms could receive the agreement of all affected in fair practices of justification. His political theory connects rights, democratic will-formation, law, and public reason. Critics ask whether ideal discourse abstracts from structural inequality, emotion, rhetoric, disability, and material dependence. The debate shows how a Kantian requirement of universal justification can become social and procedural without ceasing to be contested.'
  ],['continental-philosophy','political-philosophy','ethics'],['kant','marx','habermas'],['Dialectic of Enlightenment','Negative Dialectics','Between Facts and Norms']),
  section('ethical-revivals','Kantian ethics after the caricature of rigid rules',[
    'Twentieth- and twenty-first-century Kantian ethics is not one algorithm for testing maxims. Onora O’Neill emphasizes principles of action that others could share, the rejection of deception and coercion, and obligations shaped by vulnerability and institutions. Barbara Herman studies moral judgment, deliberation, and the ways moral principles structure an agent’s practical field. Marcia Baron reexamines duty and motivation, while Allen Wood foregrounds humanity, dignity, character, and Kant’s broader ethical corpus beyond the Groundwork.',
    'Christine Korsgaard develops an influential account of practical identity and self-constitution. Reflective agents must endorse reasons for action, and the demand for such endorsement leads toward obligations grounded in rational agency. Her work draws on Kant but also on Aristotle and contemporary action theory. Other Kantians defend value-based readings in which rational nature is an objective end, or emphasize duties, relationships, virtue, and moral feeling. These approaches disagree about whether autonomy constructs value or responds to it.',
    'Applied Kantian ethics addresses medicine, bioethics, technology, business, animals, climate, migration, and war. Respect for persons can challenge manipulation, exploitation, opaque institutions, and treating consent as a checkbox. Yet formal consent may coexist with desperation or unequal power, and a focus on rational agency may marginalize children, cognitively disabled people, nonhuman animals, dependency, and care. Contemporary Kantians respond by broadening accounts of standing, embodiment, vulnerability, and indirect or direct duty; critics argue that deeper reconstruction is required.'
  ],['ethics','deontology','political-philosophy'],['kant'],['Constructions of Reason','The Practice of Moral Judgment','The Sources of Normativity']),
  section('rawls-politics','Rawls and political Kantianism',[
    'John Rawls gave Kantian ideas a new political form. In A Theory of Justice, the original position models fair choice by withholding knowledge of social position, talent, class, race, sex, and particular conceptions of the good. The parties select principles for the basic structure rather than maxims for individual conduct. Rawls calls the view Kantian because citizens are represented as free and equal and because just principles express autonomy rather than adjustment to arbitrary fortune.',
    'Rawls later distinguishes political liberalism from a comprehensive moral doctrine. In a pluralist democracy, principles of justice should be justifiable through political values that citizens with diverse reasonable worldviews can share. This move both preserves and limits Kantian ambition. Public reason no longer depends on everyone accepting transcendental idealism or one account of moral personality. Critics question whether the category of reasonable doctrine excludes too much, whether public reason sanitizes conflict, and whether ideal theory adequately addresses racial injustice, colonial history, disability, and global inequality.',
    'Political Kantianism extends through theories of rights, republican freedom, global justice, cosmopolitanism, international law, and democratic legitimacy. It also divides. Some approaches derive principles through hypothetical agreement; others emphasize equal respect, independence from domination, or actual public justification. Libertarian, communitarian, feminist, Marxist, critical-race, realist, and decolonial critics challenge the abstraction of persons from history and power. The resulting field inherits Kant by turning autonomy into a question about institutions, not by copying Kant’s political conclusions.'
  ],['political-philosophy','ethics'],['kant','rawls'],['A Theory of Justice','Political Liberalism']),
  section('constructivisms','Constructivism and its rival Kantian interpretations',[
    'Kantian constructivism holds, in broad outline, that normative authority is explained through procedures or constitutive standards of practical reason rather than by discovering a moral order wholly independent of rational agency. Rawls introduced the label in interpreting Kant and in political theory; Korsgaard connects it to reflection and agency; O’Neill emphasizes principles that can be adopted by a plurality of agents. Constructivists disagree about whether the relevant standpoint is rational agency as such, actual social practices, or a political conception of citizens.',
    'The position faces objections from several directions. Realists argue that a procedure can generate obligations only if independent normative reasons already justify using it. Humeans question whether reason alone can motivate without desire. Aristotelian and care-ethical critics argue that abstract agency omits flourishing, relationship, emotion, dependency, and social formation. Particularists resist the hope that general principles can determine complex cases. Constructivists reply that the task is not to manufacture value by choice but to identify standards implicit in being an accountable agent among others.',
    'Not every contemporary Kantian is a constructivist. Some interpret Kant as a realist about reasons or the value of rational nature. Others regard “construction” as a method of representing justification rather than a metaphysical account of where value comes from. The dispute matters because it changes what autonomy means. Autonomy may be the source of moral law, responsiveness to a law grounded in objective value, or participation in a public process of reciprocal justification. Kantianism contains all three possibilities and the arguments among them.'
  ],['ethics','deontology','political-philosophy'],['kant','rawls'],['Groundwork of the Metaphysics of Morals','Lectures on the History of Moral Philosophy','The Sources of Normativity']),
  section('science-theory','Science, mathematics, and the revisable a priori',[
    'Kant’s philosophy of nature was formed around Euclidean geometry and Newtonian mechanics. Non-Euclidean geometry, relativity, quantum theory, evolutionary biology, and changing scientific concepts made literal preservation impossible. One response abandons synthetic a priori knowledge. Another distinguishes immutable truths from framework principles that constitute objects and measurements within a theory but can be revised during scientific change. Reichenbach, Cassirer, and later historically oriented philosophers of science develop versions of this dynamic inheritance.',
    'Michael Friedman’s account of a relativized a priori treats certain mathematical and coordinative principles as enabling empirical testing within a scientific framework. When frameworks change, philosophical reconstruction can explain how communication and rational continuity remain possible across revolutions. Critics question whether constitutive principles are genuinely a priori if history revises them and whether the model understates experimental practice, instruments, institutions, and power. The debate retains a Kantian question without retaining Kant’s answer: what makes empirical evidence count as evidence for determinate objects and laws?',
    'Contemporary philosophy also revisits Kantian themes in modality, laws of nature, explanation, model-building, cognitive architecture, and the relation between mind and world. A Kantian orientation need not claim that the human mind imposes one timeless scheme. It can ask which conceptual, material, and normative conditions make an inquiry possible and how those conditions themselves become objects of criticism. The danger is immunizing a favored science by calling its assumptions necessary; the promise is exposing background commitments that naïve empiricism leaves invisible.'
  ],['philosophy-of-science','epistemology','metaphysics'],['kant'],['Metaphysical Foundations of Natural Science','Dynamics of Reason']),
  section('contemporary-theory','Contemporary theoretical Kantian debates',[
    'Current Kant scholarship and Kant-inspired philosophy disagree about transcendental idealism. Two-object readings distinguish appearances from things in themselves; two-aspect readings distinguish ways of considering the same objects; epistemic readings emphasize limits on cognition; metaphysical readings emphasize the dependence or structure of appearances. These labels overlap imperfectly. A contemporary Kantian may defend transcendental idealism, reconstruct the arguments without it, or treat it as an historical source of questions about standpoint and objectivity.',
    'Perception creates another divide. Conceptualists argue that perceptual experience capable of justifying judgment is already shaped by conceptual capacities. Nonconceptualists defend an independent contribution from intuition, sometimes using Kant’s distinctions to resist intellectualizing perception. Debates about self-consciousness ask whether the unity of apperception establishes a substantial self, a formal condition, or an activity of synthesis. Debates about categories ask whether Kant proves necessity or at most describes features of human cognition.',
    'Metaphysical Kantians explore grounding, modality, freedom, causation, and the status of things in themselves, while naturalists ask whether transcendental philosophy can coexist with cognitive science and evolutionary explanation. Some philosophers use Kant to resist metaphysical realism; others read him as an empirical realist with a substantive metaphysics of appearances. There is no neutral package called “the Kantian framework.” Each reconstruction chooses which arguments can travel beyond the eighteenth-century system and owes an account of that choice.'
  ],['epistemology','metaphysics','philosophy-of-mind'],['kant'],['Critique of Pure Reason','Kant’s Transcendental Idealism']),
  section('criticism-exclusion','Race, gender, disability, colonialism, and the critique of universality',[
    'Kantian universalism cannot be inherited responsibly without confronting Kant’s hierarchical writings on race, sex, anthropology, culture, and historical development. Scholars disagree about whether Kant abandoned racial hierarchy and colonial justification in the 1790s, and about how changes should affect interpretation of the whole system. Late condemnations of conquest and slavery do not erase earlier taxonomies or their authority. The question is not only whether Kant personally contradicted his best principles, but whether his picture of mature rational agency was formed through excluded contrasts.',
    'Feminist philosophers have both criticized and reconstructed autonomy. Relational accounts argue that agency develops through care, dependence, institutions, embodiment, and unequal power rather than appearing as an isolated capacity. Disability theory questions moral standing tied too tightly to presently exercisable rational capacities. Critical philosophy of race examines how ideals of impartial reason and universal history can conceal a dominant standpoint. Decolonial criticism challenges narratives in which Europe represents maturity while others become earlier stages, recipients, or empirical material.',
    'Kantian replies take several forms. Some use equal dignity and the prohibition on treating persons merely as means to criticize Kant’s exclusions from within. Others revise autonomy as socially enabled, embodied, and answerable to affected agents. Still others conclude that central categories require replacement rather than repair. No automatic acquittal follows from universal language, and no single historical failure settles every argument about normativity. The live issue is whether universality can become genuinely self-critical by exposing who was denied standing in its construction and application.'
  ],['ethics','political-philosophy','feminist-philosophy'],['kant','beauvoir'],['Anthropology from a Pragmatic Point of View','Toward Perpetual Peace']),
  section('practical-tests','What a Kantian approach changes in practice',[
    'In technology ethics, a Kantian approach asks whether systems manipulate users, conceal reasons, exploit workers, or make decisions that affected persons cannot contest. Transparency matters not merely because it improves outcomes but because accountable agents should not be subjected to opaque power. Yet explanation alone is insufficient if institutions offer no meaningful ability to refuse or appeal. A checkbox can record consent while coercive conditions undermine independence.',
    'In medicine and public policy, equal standing constrains aggregate calculations that sacrifice some people as mere instruments. Universalizability tests whether an exception depends on everyone else following a rule one privately evades. Public-reason approaches ask whether coercive institutions can justify policies to diverse citizens. These tools do not mechanically deliver one answer. Describing the maxim, identifying affected agents, weighing imperfect duties, and understanding foreseeable consequences require empirical knowledge and judgment.',
    'In climate and global justice, cosmopolitan right and duties to future persons challenge state-centered convenience. Critics note that Kant’s own framework did not adequately confront colonial extraction, racial capitalism, or nonhuman nature. Contemporary Kantians therefore dispute whether duties are primarily individual, institutional, or shared across unjust structures. The practical value of the tradition lies less in a slogan about duty than in forcing power to offer reasons compatible with equal standing—and then testing whether “equal” has been defined by those already heard.'
  ],['ethics','political-philosophy','deontology'],['kant','rawls','habermas'],['The Metaphysics of Morals','Toward Perpetual Peace']),
  section('what-counts','What counts as Kantian?',[
    'No authority settles the boundary. Textual Kantians may require fidelity to Kant’s mature arguments; reconstructive Kantians preserve a problem or method while discarding historical commitments; post-Kantians treat overcoming Kant’s dualisms as the best way to inherit critique; political and ethical Kantians may accept autonomy or public justification without transcendental idealism. Neo-Kantian has a relatively precise historical meaning when it names the Marburg and Southwest schools, but a much broader and less stable meaning elsewhere.',
    'Several tests improve clarity. Which domain is at issue: cognition, metaphysics, ethics, politics, aesthetics, or method? What is retained: a priori conditions, finitude, autonomy, dignity, reflective judgment, publicity, or critique? What is revised: the thing in itself, fixed categories, individualism, scientific background, anthropocentrism, or exclusion? What rival view makes the inheritance useful? An answer can be substantially Kantian without being orthodox, but it should make its transformation visible.',
    'The deepest continuity may be a demand for reason to examine its own authority. That demand can support limits on metaphysics, justification of objective knowledge, moral self-legislation, critique of institutions, or exposure of reason’s exclusions. It can also become self-protective if the philosopher declares preferred categories necessary in advance. Kantianism is therefore best understood as an argument over how critique can be both binding and revisable, universal in aspiration and accountable to the histories it once excluded.'
  ],['epistemology','ethics','political-philosophy','philosophy-of-science'],['kant'],['Critique of Pure Reason','What Is Enlightenment?']),
  section('reading-path','A staged reading path through the reception',[
    'Begin with Kant’s Prolegomena, Groundwork, and the prefaces and introduction to the Critique of Pure Reason. These texts establish the questions of a priori conditions, limits, autonomy, and systematic critique without requiring immediate mastery of every deduction. Read What Is Enlightenment? and Toward Perpetual Peace beside selections from the Anthropology and race writings so universal claims and exclusions are visible from the start.',
    'For the first reception, read Reinhold or a reliable history before sampling Fichte, Schelling, and Hegel. The goal is to see why the thing in itself, the division of faculties, and the relation between nature and freedom seemed unstable. Then compare Schopenhauer’s transformation with neo-Kantian selections from Cohen, Natorp, Windelband, Rickert, and Cassirer. Keep the Marburg focus on science distinct from the Southwest focus on value and history.',
    'For twentieth-century inheritances, choose parallel routes. In theoretical philosophy, compare Strawson, Sellars, and McDowell with phenomenology and Heidegger. In practical philosophy, compare Rawls, O’Neill, Korsgaard, Herman, Wood, and Habermas, then read realist, Humean, feminist, critical-race, disability, and decolonial critics. Ask in every case not “Is this the true Kantianism?” but “Which Kantian problem is being reconstructed, what does the reconstruction illuminate, and what does it leave out?”'
  ],['german-idealism','analytic-philosophy','continental-philosophy','ethics'],['kant','fichte','hegel','schopenhauer','rawls','habermas'],['Prolegomena to Any Future Metaphysics','The Bounds of Sense','The Sources of Normativity'])
];

